import 'package:flutter/material.dart'; import 'package:url_launcher/url_launcher.dart'; import '../models/report.dart'; import '../services/report_service.dart'; import '../utils/constants.dart'; import '../widgets/status_badge.dart';
class DashboardReportDetailsScreen extends StatefulWidget { const DashboardReportDetailsScreen({required this.report,required this.onChanged,super.key});final IncidentReport report;final VoidCallback onChanged; @override State<DashboardReportDetailsScreen> createState()=>_DashboardReportDetailsScreenState(); }
class _DashboardReportDetailsScreenState extends State<DashboardReportDetailsScreen>{bool busy=false; Future<void> update(String value)async{setState(()=>busy=true);try{await ReportService().updateStatus(widget.report.id,value);widget.onChanged();if(mounted)Navigator.pop(context);}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Status could not be updated. Check your responder permissions.')));}finally{if(mounted)setState(()=>busy=false);}}
  @override Widget build(BuildContext context){final r=widget.report;final next=switch(r.status){'PENDING'=>'RECEIVED','RECEIVED'=>'ASSIGNED','ASSIGNED'=>'RESPONDER_ON_WAY','RESPONDER_ON_WAY'=>'ARRIVED','ARRIVED'=>'RESOLVED',_=>null};return Scaffold(appBar:AppBar(title:Text(r.reportId)),body:Padding(padding:const EdgeInsets.all(20),child:ListView(children:[Text(r.incidentType,style:Theme.of(context).textTheme.headlineSmall),StatusBadge(r.status),const SizedBox(height:18),Text(r.description),const Divider(height:32),Text('Created: ${r.createdLabel}'),Text('Coordinates: ${r.latitude.toStringAsFixed(6)}, ${r.longitude.toStringAsFixed(6)}'),if(r.locationAccuracy!=null)Text('Device GPS accuracy: ±${r.locationAccuracy!.toStringAsFixed(1)} m'),if(r.receivedAt!=null)Text('Receiving timestamp: ${r.receivedAt!.toLocal()}'),if(r.deliveryTime!=null)Text('Alert delivery time: ${r.deliveryTime}'),const SizedBox(height:12),OutlinedButton.icon(onPressed:()=>launchUrl(Uri.parse('https://www.openstreetmap.org/?mlat=${r.latitude}&mlon=${r.longitude}#map=18/${r.latitude}/${r.longitude}'),mode:LaunchMode.externalApplication),icon:const Icon(Icons.map),label:const Text('VIEW INCIDENT LOCATION ON MAP')),const SizedBox(height:24),if(next!=null)FilledButton.icon(onPressed:busy?null:()=>update(next),icon:const Icon(Icons.update),label:Text(busy?'UPDATING…':'MARK AS ${next.replaceAll('_',' ')}')),if(r.status!='RESOLVED'&&r.status!='CANCELLED')TextButton(onPressed:busy?null:()=>update('CANCELLED'),child:const Text('Cancel report'))])));}
}
